	ids := slice.Map(tracks, func(e model.PlaylistTrack) model.ArtworkID {
		return e.AlbumCoverArtID()
	})
	rand.Seed(time.Now().UnixNano())
	rand.Shuffle(len(ids), func(i, j int) { ids[i], ids[j] = ids[j], ids[i] })
	return ids
}

